// Setup & Config Check
// Reads "Your keys" + "Settings", checks the sheet can be read, and lists posts already saved
const keys = $('Your keys').first().json;
const cfg = $('Settings').first().json;
const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const isBlank = (v) => !str(v) || /^PASTE_/i.test(str(v));

const missingKeys = ['sheet_url', 'serpapi_api_key', 'youtube_api_key', 'apify_api_token'].filter(k => isBlank(keys[k]));
if (missingKeys.length) throw new Error('Fill these in the "Your keys" node: ' + missingKeys.join(', '));

const required = ['app_name', 'play_store_app_id', 'app_store_app_id', 'trustpilot_domain', 'country', 'research_goal', 'relevance_keywords', 'theme_list'];
const missing = required.filter(k => !str(cfg[k]));
if (missing.length) throw new Error('Fill these in the "Settings" node: ' + missing.join(', '));
const num = (k, d) => { const n = Number(cfg[k]); return Number.isFinite(n) && n > 0 ? n : d; };

// Sheet check + posts already saved in "5 Raw Data"
const errText = (e) => (typeof e === 'string' ? e : (e && (e.message || JSON.stringify(e))) || 'unknown error').slice(0, 200);
const sheetRows = $('Check Existing Data').all();
const sheetErr = sheetRows.find(i => i.json && i.json.error);
if (sheetErr) {
  throw new Error('Could not read the Google Sheet. Check sheet_url in "Your keys", your Google Sheets login, and that the sheet has a tab named "5 Raw Data". Details: ' + errText(sheetErr.json.error));
}
const existingIds = sheetRows
  .map(i => i.json['Post ID'])
  .filter(v => v !== undefined && v !== null && String(v).trim() !== '')
  .map(v => String(v));

// Video clips already saved in "6 Voice Data" (needed only when video transcripts are on)
const tv = Number(cfg.youtube_transcript_videos);
const transcriptVideos = Number.isFinite(tv) && tv >= 0 ? Math.min(Math.floor(tv), 25) : 15;
let voiceRows = [];
try { voiceRows = $('Check Existing Voice Data').all(); } catch (e) { voiceRows = []; }
const voiceErr = voiceRows.find(i => i.json && i.json.error);
if (voiceErr && transcriptVideos > 0) {
  throw new Error('Could not read the "6 Voice Data" tab. Add a tab with that exact name and its headers in row 1, or set youtube_transcript_videos to 0 in Settings. Details: ' + errText(voiceErr.json.error));
}
const existingVoiceIds = voiceErr ? [] : voiceRows
  .map(i => i.json['Post ID'])
  .filter(v => v !== undefined && v !== null && String(v).trim() !== '')
  .map(v => String(v));

const now = new Date();
const lookback = num('lookback_days', 365);
const after = new Date(now.getTime() - lookback * 86400000);
const pad = (n) => String(n).padStart(2, '0');

return [{
  json: {
    run_id: 'run_' + now.toISOString().replace(/[:.]/g, '-').slice(0, 19),
    run_started_at: now.toISOString(),
    app_name: str(cfg.app_name),
    play_store_app_id: str(cfg.play_store_app_id),
    app_store_app_id: str(cfg.app_store_app_id),
    trustpilot_domain: str(cfg.trustpilot_domain),
    country: str(cfg.country).toLowerCase(),
    research_goal: str(cfg.research_goal),
    relevance_keywords: str(cfg.relevance_keywords).split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
    theme_list: str(cfg.theme_list).split(',').map(s => s.trim()).filter(Boolean),
    source_order: [...new Set([...str(cfg.source_order).split(',').map(x => x.trim()).filter(Boolean),
      'App Store', 'Play Store', 'YouTube', 'YouTube Transcripts', 'TradingQ&A', 'Quora', 'Trustpilot', 'Google Search'])],
    lookback_days: lookback,
    published_after: after.toISOString().replace(/\.\d{3}Z$/, 'Z'),
    after_date: after.toISOString().slice(0, 10),
    google_tbs: `cdr:1,cd_min:${pad(after.getUTCMonth() + 1)}/${pad(after.getUTCDate())}/${after.getUTCFullYear()}`,
    youtube_max_videos: Math.min(num('youtube_max_videos', 25), 50),
    youtube_max_comments_per_video: Math.min(num('youtube_max_comments_per_video', 100), 100),
    // video transcripts (spoken data): 0 = off
    youtube_transcript_videos: transcriptVideos,
    transcript_language: str(cfg.transcript_language) || 'hi',
    transcript_window_seconds: Math.max(30, Math.min(num('transcript_window_seconds', 60), 180)),
    transcript_max_windows_per_video: Math.min(num('transcript_max_windows_per_video', 6), 20),
    play_store_pages: Math.min(num('play_store_pages', 3), 10),
    app_store_pages: Math.min(num('app_store_pages', 10), 10),
    tradingqna_max_queries: Math.min(num('tradingqna_max_queries', 8), 15),
    google_max_queries: Math.min(num('google_max_queries', 4), 10),
    quora_max_queries: Math.min(num('quora_max_queries', 4), 10),
    quora_answers_per_query: Math.max(10, Math.min(num('quora_answers_per_query', 50), 200)),
    quora_time_filter: str(cfg.quora_time_filter) || 'Past Year',
    trustpilot_max_reviews: Math.min(num('trustpilot_max_reviews', 100), 1000),
    apify_quora_actor: str(cfg.apify_quora_actor).replace('/', '~') || 'fatihtahta~quora-scraper',
    apify_trustpilot_actor: str(cfg.apify_trustpilot_actor).replace('/', '~') || 'nikita-sviridenko~trustpilot-reviews-scraper',
    target_relevant_posts: num('target_relevant_posts', 350),
    golden_set_size: num('golden_set_size', 20),
    tagging_batch_size: Math.min(num('tagging_batch_size', 20), 40),
    min_text_length: num('min_text_length', 20),
    similarity_threshold: Math.min(Number(cfg.similarity_threshold) || 0.85, 1),
    existing_post_ids: [...existingIds, ...existingVoiceIds],
    existing_post_count: existingIds.length + existingVoiceIds.length,
  },
}];

// Parse Research Plan: turns the Research Agent's answer into search inputs for all sources
const s = $('Setup & Config Check').first().json;
const out = $input.first().json;
const raw = String(out.text ?? out.output ?? '');
if (!raw.trim()) throw new Error('Research Agent returned no text. Check the Gemini Model node and its credential.');

function parseJson(t) {
  const c = t.replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(c); } catch (e) {
    const m = c.match(/\{[\s\S]*\}/);
    if (m) return JSON.parse(m[0]);
    throw new Error('Research Agent did not return valid JSON. Output was: ' + t.slice(0, 300));
  }
}
const plan = parseJson(raw);
const clean = (a, n) => [...new Set((Array.isArray(a) ? a : [])
  .map(x => String(x).replace(/site:\S+/gi, '').trim())
  .filter(x => x.length >= 3))]
  .slice(0, n);

const youtube = clean(plan.youtube_queries, 5);
const tradingqna = clean(plan.tradingqna_queries, s.tradingqna_max_queries);
const google = clean(plan.google_queries, s.google_max_queries);
const quora = clean(plan.quora_queries, s.quora_max_queries);
const empty = Object.entries({ youtube, tradingqna, google, quora }).filter(([, v]) => !v.length).map(([k]) => k);
if (empty.length) throw new Error('Research Agent returned no queries for: ' + empty.join(', ') + '. Output: ' + raw.slice(0, 300));

const pages = (n) => Array.from({ length: n }, (_, i) => i + 1);
return [{
  json: {
    youtube_queries: youtube,
    youtube_q: youtube.join(' | '),   // YouTube search treats | as OR
    tradingqna_queries: tradingqna,
    google_queries: google,
    quora_queries: quora,
    app_store_pages: pages(s.app_store_pages),
  },
}];

// Standardize Data: common JSON format for all 8 sources, extract key fields, add source metadata
const s = $('Setup & Config Check').first().json;
const plan = $('Parse Research Plan').first().json;
const all = (name) => { try { return $(name).all(); } catch (e) { return []; } };

const decode = (t) => String(t ?? '')
  .replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&#(\d+);/g, (m, c) => String.fromCharCode(Number(c)));
const iso = (d) => { if (!d) return ''; const t = new Date(d); return isNaN(t.getTime()) ? '' : t.toISOString(); };
const hash = (t) => { let h = 0; const x = String(t || ''); for (let i = 0; i < x.length; i++) { h = ((h << 5) - h + x.charCodeAt(i)) | 0; } return Math.abs(h).toString(36); };
const host = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch (e) { return ''; } };
const asJson = (j) => { if (j && typeof j.data === 'string') { try { return JSON.parse(j.data); } catch (e) { return {}; } } return j || {}; };

const records = [];
const add = (r) => records.push({
  source: r.source,
  source_type: r.source_type,
  post_id: String(r.post_id ?? ''),
  title: decode(r.title).slice(0, 300),
  text: decode(r.text).slice(0, 5000),
  author: decode(r.author).slice(0, 120),
  rating: r.rating ?? '',
  likes: r.likes ?? '',
  post_date: iso(r.post_date),
  url: r.url || '',
  search_query: r.search_query || '',
});

// ---- YouTube (videos + comments) ----
const vids = all('YouTube Split Videos');
const comments = all('YouTube Get Comments');
vids.forEach((v, i) => {
  const vid = v.json.id && v.json.id.videoId;
  if (!vid) return;
  const sn = v.json.snippet || {};
  add({
    source: 'YouTube', source_type: 'video', post_id: 'yt_v_' + vid,
    title: sn.title, text: [sn.title, sn.description].filter(Boolean).join(' - '),
    author: sn.channelTitle, post_date: sn.publishedAt,
    url: 'https://www.youtube.com/watch?v=' + vid, search_query: plan.youtube_q,
  });
  const c = comments[i] ? comments[i].json : {};
  for (const t of (c.items || [])) {
    const top = t.snippet && t.snippet.topLevelComment;
    if (!top) continue;
    const cs = top.snippet || {};
    add({
      source: 'YouTube', source_type: 'comment', post_id: 'yt_c_' + top.id,
      title: sn.title, text: cs.textOriginal || cs.textDisplay,
      author: cs.authorDisplayName, likes: cs.likeCount, post_date: cs.publishedAt,
      url: `https://www.youtube.com/watch?v=${vid}&lc=${top.id}`, search_query: plan.youtube_q,
    });
  }
});

// ---- YouTube Transcripts (what is said in the videos, SerpApi) ----
// Each transcript is cut into ~60-second windows around mentions of a SIP keyword or the app name; one window = one post.
const escRe = (k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const anchorWords = [...new Set([...s.relevance_keywords, String(s.app_name || '').toLowerCase()])].filter(Boolean);
const anchorRe = new RegExp('(^|[^a-z0-9])(' + anchorWords.map(escRe).join('|') + ')(?=$|[^a-z0-9])', 'i');
const SPONSOR_RE = /sponsor|paid partnership|#ad\b|affiliate|referral|refer(ral)? code|use my (link|code)|groww\.app\.link|app\.groww\.in\/v3/i;
const videoMeta = {};
for (const v of vids) { const id = v.json.id && v.json.id.videoId; if (id) videoMeta[id] = { ...(v.json.snippet || {}) }; }
for (const item of all('YouTube Video Details')) {
  for (const v of (asJson(item.json).items || [])) if (v && v.id) videoMeta[v.id] = { ...(videoMeta[v.id] || {}), ...(v.snippet || {}) };
}
const winMs = s.transcript_window_seconds * 1000;
for (const item of all('YouTube Get Transcripts')) {
  const d = asJson(item.json);
  if (!d || d.error) continue;
  const vid = (d.search_parameters || {}).v;
  const lines = (Array.isArray(d.transcript) ? d.transcript : [])
    .map(x => ({ start: Number(x && x.start_ms) || 0, text: String((x && x.snippet) || '').replace(/\s+/g, ' ').trim() }))
    .filter(x => x.text)
    .sort((a, b) => a.start - b.start);
  if (!vid || !lines.length) continue;
  const m = videoMeta[vid] || {};
  const sponsoredVideo = SPONSOR_RE.test([m.title, m.description].filter(Boolean).join(' '));
  let lastEnd = -1;
  let made = 0;
  for (const ln of lines) {
    if (made >= s.transcript_max_windows_per_video) break;
    if (ln.start <= lastEnd || !anchorRe.test(ln.text)) continue;
    const from = Math.max(lastEnd + 1, ln.start - winMs / 3);
    const to = ln.start + (2 * winMs) / 3;
    const text = lines.filter(x => x.start >= from && x.start <= to).map(x => x.text).join(' ');
    lastEnd = to;
    made++;
    const sec = Math.floor(from / 1000);
    const sponsored = sponsoredVideo || /sponsor/i.test(text);
    add({
      source: 'YouTube Transcripts', source_type: 'transcript', post_id: `yt_t_${vid}_${sec}`,
      title: (sponsored ? '[Possible sponsored/referral] ' : '') + (m.title || ''),
      text, author: m.channelTitle, post_date: m.publishedAt,
      url: `https://www.youtube.com/watch?v=${vid}&t=${sec}s`, search_query: plan.youtube_q,
    });
  }
}

// ---- Play Store reviews (SerpApi) ----
for (const item of all('Play Store Reviews')) {
  for (const r of (asJson(item.json).reviews || [])) {
    const id = r.id || hash(r.title + r.snippet + r.date);
    add({
      source: 'Play Store', source_type: 'review', post_id: 'gp_' + id,
      title: '', text: r.snippet, author: r.title, rating: r.rating, likes: r.likes,
      post_date: r.iso_date || r.date,
      url: `https://play.google.com/store/apps/details?id=${s.play_store_app_id}&reviewId=${encodeURIComponent(r.id || '')}`,
      search_query: 'newest reviews',
    });
  }
}

// ---- App Store reviews (Apple public RSS) ----
for (const item of all('App Store Reviews')) {
  const feed = asJson(item.json).feed || {};
  let entries = feed.entry || [];
  if (!Array.isArray(entries)) entries = [entries];
  for (const e of entries) {
    if (!e['im:rating']) continue; // skip app-info entry
    const id = (e.id && e.id.label) || hash(JSON.stringify(e));
    const title = e.title && e.title.label;
    const body = e.content && e.content.label;
    add({
      source: 'App Store', source_type: 'review', post_id: 'as_' + id,
      title, text: [title, body].filter(Boolean).join('. '),
      author: e.author && e.author.name && e.author.name.label,
      rating: Number(e['im:rating'].label),
      likes: e['im:voteSum'] ? Number(e['im:voteSum'].label) : '',
      post_date: e.updated && e.updated.label,
      url: `https://apps.apple.com/${s.country}/app/id${s.app_store_app_id}?see-all=reviews`,
      search_query: 'most recent reviews',
    });
  }
}

// ---- TradingQ&A forum (Discourse search) ----
const tq = all('TradingQnA Search');
const tqQueries = all('TradingQnA Split Queries');
tq.forEach((item, i) => {
  const d = asJson(item.json);
  const q = tqQueries[i] ? tqQueries[i].json.tradingqna_queries : '';
  const topics = {};
  for (const t of (d.topics || [])) topics[t.id] = t;
  for (const p of (d.posts || [])) {
    const t = topics[p.topic_id] || {};
    add({
      source: 'TradingQ&A', source_type: 'forum', post_id: 'tq_' + p.id,
      title: t.title, text: [t.title, p.blurb].filter(Boolean).join(' - '),
      author: p.username, likes: p.like_count, post_date: p.created_at,
      url: `https://tradingqna.com/t/${t.slug || 'topic'}/${p.topic_id}/${p.post_number || 1}`,
      search_query: q,
    });
  }
});

// ---- Google Search (news + blogs, SerpApi) ----
const gr = all('Google Search');
const gQueries = all('Google Split Queries');
gr.forEach((item, i) => {
  const d = asJson(item.json);
  const q = gQueries[i] ? gQueries[i].json.google_queries : '';
  for (const r of (d.organic_results || [])) {
    if (!r.link) continue;
    add({
      source: 'Google Search', source_type: 'web', post_id: 'g_' + hash(r.link),
      title: r.title, text: [r.title, r.snippet].filter(Boolean).join(' - '),
      author: r.source || host(r.link), post_date: r.date, url: r.link, search_query: q,
    });
  }
});

// ---- Apify helpers: read a field by any of several possible names (actors differ slightly) ----
const get = (o, path) => path.split('.').reduce((v, k) => (v && typeof v === 'object') ? v[k] : undefined, o);
const pick = (o, paths) => { for (const p of paths) { const v = get(o, p); if (v !== undefined && v !== null && v !== '') return v; } return ''; };
const asText = (v) => typeof v === 'string' ? v : (v && typeof v === 'object' ? (v.text || v.name || v.title || '') : String(v || ''));

// ---- Quora (Apify Quora Scraper: full answers to the Research Agent's Quora questions) ----
const qaQueries = $('Parse Research Plan').first().json.quora_queries.join(' | ');
for (const item of all('Quora Search')) {
  const r = item.json || {};
  if (r.error) continue;
  const answer = pick(r, ['answer.text', 'answer.content', 'answerText', 'answer_text', 'text', 'content']);
  const question = asText(pick(r, ['question.title', 'question.text', 'questionTitle', 'question', 'title']));
  if (!answer && !question) continue;
  const url = pick(r, ['answer.url', 'url', 'question.url', 'link']);
  add({
    source: 'Quora', source_type: answer ? 'forum' : 'web',
    post_id: 'qa_' + (pick(r, ['answer.id', 'id', 'answerId']) || hash(url + answer)),
    title: question, text: answer ? asText(answer) : question,
    author: asText(pick(r, ['answer.author.name', 'answer.author', 'author.name', 'author'])) || 'Quora',
    likes: pick(r, ['answer.metrics.upvotes', 'upvotes', 'answer.upvotes']),
    post_date: pick(r, ['answer.posted_at', 'posted_at', 'createdAt', 'date', 'question.posted_at']),
    url, search_query: qaQueries,
  });
}

// ---- Trustpilot (Apify Trustpilot Reviews Scraper) ----
for (const item of all('Trustpilot Reviews')) {
  const r = item.json || {};
  if (r.error) continue;
  const body = pick(r, ['reviewBody', 'reviewText', 'text', 'content', 'body']);
  const head = pick(r, ['reviewHeadline', 'reviewTitle', 'title', 'headline']);
  if (!body && !head) continue;
  const id = pick(r, ['reviewId', 'id']) || hash(head + body);
  add({
    source: 'Trustpilot', source_type: 'review', post_id: 'tp_' + id,
    title: head, text: [head, body].filter(Boolean).join('. '),
    author: asText(pick(r, ['authorName', 'reviewerName', 'consumer.displayName', 'author'])),
    rating: pick(r, ['ratingValue', 'rating', 'stars']), likes: pick(r, ['likes']),
    post_date: pick(r, ['datePublished', 'reviewDate', 'publishedDate', 'dates.publishedDate', 'date']),
    url: pick(r, ['reviewUrl', 'url']) || ('https://www.trustpilot.com/reviews/' + id), search_query: 'newest reviews',
  });
}

if (!records.length) {
  throw new Error('No data was collected from any source. Check the source nodes for errors (keys, quota, network).');
}

return records.map(r => ({
  json: { ...r, run_id: s.run_id, collected_at: s.run_started_at, app_name: s.app_name },
}));

// Remove Duplicates: match by content similarity, keep highest quality
const s = $('Setup & Config Check').first().json;
const threshold = s.similarity_threshold;
const existing = new Set(s.existing_post_ids || []);

const norm = (t) => String(t || '').toLowerCase().normalize('NFKC')
  .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
const tokens = (t) => new Set(norm(t).split(' ').filter(w => w.length > 2));
const quality = (r) => Math.min(String(r.text || '').length, 1000) / 100
  + (Number(r.likes) || 0) + (r.rating !== '' && r.rating !== undefined ? 1 : 0);

// 1) Same post fetched twice (same post_id) or already saved in an earlier run
const byId = new Map();
let alreadySaved = 0;
for (const { json: r } of $input.all()) {
  if (existing.has(r.post_id)) { alreadySaved++; continue; }
  const prev = byId.get(r.post_id);
  if (!prev) { byId.set(r.post_id, { ...r, duplicates_merged: 0 }); continue; }
  if (quality(r) > quality(prev)) byId.set(r.post_id, { ...r, duplicates_merged: prev.duplicates_merged + 1 });
  else prev.duplicates_merged += 1;
}

// 2) Near-duplicate content (reposts, same text under different ids)
const list = [...byId.values()].sort((a, b) => quality(b) - quality(a)); // best first, so the kept copy is the highest quality
const kept = [];
for (const r of list) {
  const n = norm(r.text);
  const tk = tokens(r.text);
  let dupOf = null;
  for (const k of kept) {
    if (n && k._n === n && (n.length >= 40 || k.author === r.author)) { dupOf = k; break; }
    if (tk.size >= 8 && k._tk.size >= 8) {
      let inter = 0;
      for (const w of tk) if (k._tk.has(w)) inter++;
      const jaccard = inter / (tk.size + k._tk.size - inter);
      if (jaccard >= threshold) { dupOf = k; break; }
    }
  }
  if (dupOf) { dupOf.duplicates_merged += 1 + r.duplicates_merged; continue; }
  r._n = n; r._tk = tk;
  kept.push(r);
}

if (!kept.length) {
  throw new Error(`No new posts: all ${alreadySaved} collected posts are already in Posts Data.`);
}
return kept.map(({ _n, _tk, ...r }) => ({ json: r }));

// Validate & Enrich: check required fields, enrich with context, add tags (source, date, etc.)
// Output columns = the "5 Raw Data" tab
const s = $('Setup & Config Check').first().json;
const lookbackStart = new Date(s.published_after).getTime();
const REQUIRED = ['post_id', 'source', 'text', 'url'];

// save rows grouped by source, in the order set in Settings > source_order
const rank = (src) => { const i = s.source_order.indexOf(src); return i < 0 ? 99 : i; };
const ordered = $input.all().map((x, i) => ({ ...x, i })).sort((a, b) => (rank(a.json.source) - rank(b.json.source)) || (a.i - b.i));

return ordered.map(({ json: r }) => {
  const missing = REQUIRED.filter(k => !String(r[k] ?? '').trim());
  const textLen = String(r.text || '').trim().length;
  const d = r.post_date ? new Date(r.post_date) : null;
  const hasDate = d && !isNaN(d.getTime());

  let status = 'Valid';
  if (missing.length) status = 'Invalid: missing required field';
  else if (textLen < s.min_text_length) status = 'Invalid: text too short';
  else if (hasDate && d.getTime() < lookbackStart) status = 'Invalid: older than lookback';

  const notes = [...missing];
  if (!hasDate) notes.push('date (optional)');

  return {
    json: {
      'Run ID': s.run_id,
      'Collected At': s.run_started_at,
      'Post ID': r.post_id,
      'Source': r.source,
      'Type': r.source_type,
      'Title / Context': r.title,
      'Text': r.text,
      'Author': r.author,
      'Rating': r.rating,
      'Likes': r.likes,
      'Post Date': hasDate ? r.post_date.slice(0, 10) : '',
      'Link': r.url,
      'Found By (search)': r.search_query,
      'Duplicates Merged': r.duplicates_merged || 0,
      'Status': status,
      'Missing Fields': notes.join(', '),
    },
  };
});

// Clean & Prepare: get this run's new records, remove noise, filter invalid posts, normalize text,
// keep up to <target_relevant_posts> SIP-related posts (balanced across sources) for AI tagging
const s = $('Setup & Config Check').first().json;
// written posts are read back from "5 Raw Data"; this run's video clips go to "6 Voice Data", so they are taken from Validate & Enrich
const clipRows = (() => { try { return $('Validate & Enrich').all().map(i => i.json).filter(r => r['Type'] === 'transcript' && String(r['Run ID']) === s.run_id); } catch (e) { return []; } })();
const rows = [...$input.all().map(i => i.json).filter(r => String(r['Run ID']) === s.run_id && r['Type'] !== 'transcript'), ...clipRows];
if (!rows.length) throw new Error('No posts for ' + s.run_id + ' in "5 Raw Data" and no video clips from this run.');

const esc = (k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const kwRe = new RegExp('(^|[^a-z0-9])(' + s.relevance_keywords.map(esc).join('|') + ')(?=$|[^a-z0-9])', 'i');

const clean = (t) => String(t || '')
  .normalize('NFKC')
  .replace(/<[^>]+>/g, ' ')                                    // html
  .replace(/https?:\/\/\S+|www\.\S+/g, ' ')                     // links
  .replace(/[\p{Extended_Pictographic}️‍]/gu, ' ')    // emojis
  .replace(/(.)\1{4,}/g, '$1$1$1')                              // "soooooo" -> "sooo"
  .replace(/\s+/g, ' ')
  .trim();

const stats = { saved_rows: rows.length, invalid: 0, too_short_after_cleaning: 0, not_sip_related: 0, relevant_found: 0, analysed: 0 };
const relevant = [];
for (const r of rows) {
  if (r['Status'] !== 'Valid') { stats.invalid++; continue; }
  const text = clean(r['Text']);
  if (text.length < s.min_text_length) { stats.too_short_after_cleaning++; continue; }
  const context = (r['Type'] === 'comment' || r['Type'] === 'transcript') ? clean(r['Title / Context']).slice(0, 150) : '';
  if (!kwRe.test(text + ' ' + context)) { stats.not_sip_related++; continue; }
  relevant.push({
    post_id: String(r['Post ID']), source: r['Source'], source_type: r['Type'],
    url: r['Link'], post_date: r['Post Date'], rating: r['Rating'], likes: Number(r['Likes']) || 0,
    context, text: text.slice(0, 1500),
  });
}
stats.relevant_found = relevant.length;
if (!relevant.length) {
  throw new Error('No SIP-related posts left after cleaning. Stats: ' + JSON.stringify(stats) + '. Widen relevance_keywords in Settings.');
}

// Keep up to the target, taking sources in turn so no single source dominates.
// Inside each source, richer posts first (people's own words over search snippets, longer, more liked).
const typeWeight = { review: 3, comment: 3, forum: 3, transcript: 2, video: 1, web: 1 };
// windows from videos that look sponsored go to the back of their source's queue
const quality = (p) => (typeWeight[p.source_type] || 1) * 1000 + Math.min(p.text.length, 600) + p.likes * 5
  - (/^\[possible sponsored/i.test(p.context) ? 500 : 0);
const bySource = {};
for (const p of relevant) (bySource[p.source] = bySource[p.source] || []).push(p);
Object.values(bySource).forEach(list => list.sort((a, b) => quality(b) - quality(a)));
const queues = Object.values(bySource);
const picked = [];
while (picked.length < s.target_relevant_posts && queues.some(q => q.length)) {
  for (const q of queues) {
    if (q.length && picked.length < s.target_relevant_posts) picked.push(q.shift());
  }
}
stats.analysed = picked.length;

const size = s.tagging_batch_size;
const count = Math.ceil(picked.length / size);
const out = [];
for (let i = 0; i < picked.length; i += size) {
  out.push({ json: { batch_no: out.length + 1, batch_count: count, posts: picked.slice(i, i + size), stats } });
}
return out;

// Parse Tags: one row per post for "2 Feedback Analysis".
// Source, link and date come from the data (never from the AI); every evidence quote is checked word-for-word.
const s = $('Setup & Config Check').first().json;
const batches = $('Clean & Prepare').all();
const themeCase = {};
for (const t of s.theme_list) themeCase[t.toLowerCase()] = t;
const BEHAVIOURS = ['Started', 'Continuing', 'Paused', 'Reduced', 'Stopped', 'Not stated'];
const norm = (t) => String(t || '').toLowerCase().normalize('NFKC')
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

function parseArr(t) {
  const c = String(t || '').replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(c); } catch (e) {
    const m = c.match(/\[[\s\S]*\]/);
    if (m) return JSON.parse(m[0]);
    throw new Error('unreadable AI output');
  }
}
const txt = (v, n = 300) => {
  const t = String(v ?? '').trim();
  return /^(n\/?a|none|null|not stated|not mentioned|unknown|-)$/i.test(t) ? '' : t.slice(0, n);
};

const rows = [];
const problems = [];
const taggedAt = new Date().toISOString();
$input.all().forEach((item, i) => {
  const batch = batches[i] ? batches[i].json.posts : [];
  const byId = {};
  for (const p of batch) byId[p.post_id] = p;
  if (item.json.error) { problems.push({ batch: i + 1, why: 'AI call failed: ' + String(item.json.error.message || item.json.error).slice(0, 150), dropped: batch.length }); return; }
  let arr;
  try { arr = parseArr(item.json.text ?? item.json.output); } catch (e) { problems.push({ batch: i + 1, why: 'AI answer was not valid JSON', dropped: batch.length }); return; }
  if (!Array.isArray(arr)) { problems.push({ batch: i + 1, why: 'AI answer was not a list', dropped: batch.length }); return; }
  const seen = new Set();
  let unknownIds = 0;
  for (const t of arr) {
    const p = byId[String(t && t.post_id)];
    if (!p) { unknownIds++; continue; }
    if (seen.has(p.post_id)) continue;
    seen.add(p.post_id);
    const rawThemes = (Array.isArray(t.theme) ? t.theme : [t.theme]).map(x => String(x || '').trim()).filter(Boolean);
    let themes = rawThemes.map(x => themeCase[x.toLowerCase()]).filter(Boolean);
    const offList = rawThemes.filter(x => !themeCase[x.toLowerCase()]);
    themes = [...new Set(themes)].slice(0, 3);
    if (!themes.length) themes = [themeCase['other'] || 'Other'];
    const behaviour = BEHAVIOURS.find(b => b.toLowerCase() === String(t.behaviour || '').trim().toLowerCase()) || 'Not stated';
    const quote = txt(t.quote, 400);
    const quoteOk = !!quote && norm(p.text).includes(norm(quote));
    const explicit = t.explicit === true || String(t.explicit).toLowerCase() === 'true';
    const theme = themes.join(', ');
    rows.push({
      json: {
        // ---- columns of "2 Feedback Analysis" ----
        'Run ID': s.run_id,
        'Post ID': p.post_id,
        'Source': p.source,
        'Post Date': p.post_date,
        'Link': p.url,
        'Post (cleaned)': p.text,
        'Theme(s)': theme,
        'Behaviour': behaviour,
        'Q1 Why they started & what they expected': txt(t.q1_why_started),
        'Q2 What changed after starting': txt(t.q2_change_after_start),
        'Q3 Why they paused, reduced or stopped': txt(t.q3_why_paused_reduced_stopped),
        'Q4 What they check & how often': txt(t.q4_what_they_check),
        'Q5 What confuses or worries them in the app': txt(t.q5_in_app_confusion),
        'Q6 What they do outside the app when unsure': txt(t.q6_outside_app_action),
        'Q7 Continue vs drop-off signal': txt(t.q7_continue_or_dropoff_signal),
        'Q8 Income stability': txt(t.q8_income_stability, 80),
        'Q8 Age': txt(t.q8_age, 40),
        'Q8 Source of money': txt(t.q8_source_of_money, 80),
        'Q8 Influenced by': txt(t.q8_influenced_by, 80),
        'Q9 Unmet need': txt(t.q9_unmet_need),
        'Evidence Quote': quote,
        'Stated or Inferred': explicit ? 'Stated' : 'Inferred',
        'Quote Verified': quoteOk ? 'Yes' : 'No',
        // ---- internal fields for the next steps (not saved to the sheet) ----
        run_id: s.run_id, post_id: p.post_id, source: p.source, source_type: p.source_type,
        url: p.url, post_date: p.post_date, text: p.text, theme, behaviour,
        reason: txt(t.q3_why_paused_reduced_stopped) || txt(t.q1_why_started) || txt(t.q5_in_app_confusion) || txt(t.q9_unmet_need),
        explicit, quote, quote_ok: quoteOk, off_list_themes: offList.join(', '), tagged_at: taggedAt,
        segments: {
          income_stability: txt(t.q8_income_stability, 80), age: txt(t.q8_age, 40),
          source_of_money: txt(t.q8_source_of_money, 80), influenced_by: txt(t.q8_influenced_by, 80),
        },
      },
    });
  }
  const skipped = batch.length - seen.size;
  if (skipped > 0) problems.push({ batch: i + 1, why: 'AI did not return a label for some posts', dropped: skipped });
  if (unknownIds > 0) problems.push({ batch: i + 1, why: 'AI returned post IDs that were not in the batch (ignored)', dropped: 0, count: unknownIds });
});

if (!rows.length) throw new Error('AI Tagging Agent returned no usable labels. ' + JSON.stringify(problems).slice(0, 400));
// save rows grouped by source, in the order set in Settings > source_order
const rank = (src) => { const i = s.source_order.indexOf(src); return i < 0 ? 99 : i; };
const ordered = rows.map((r, i) => ({ r, i })).sort((a, b) => (rank(a.r.json.source) - rank(b.r.json.source)) || (a.i - b.i)).map(x => x.r);
ordered[0].json.tagging_problems = problems; // read later by the AI Evidence Log
return ordered;

// Group by Themes: cluster similar issues, build theme summary
const rows = $('Parse Tags').all().map(i => i.json);

const groups = {};
for (const r of rows) {
  for (const th of String(r.theme).split(', ')) {
    if (!th || th.toLowerCase() === 'not relevant') continue;
    if (!groups[th]) groups[th] = { theme: th, posts: [] };
    groups[th].posts.push(r);
  }
}

// cluster similar issues inside each theme by the wording of the tagged reason
const tok = (t) => new Set(String(t || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(w => w.length > 3));
const sim = (a, b) => { let i = 0; for (const w of a) if (b.has(w)) i++; const u = a.size + b.size - i; return u ? i / u : 0; };

const summaries = Object.values(groups).map(g => {
  const clusters = [];
  for (const p of g.posts) {
    const tk = tok(p.reason);
    if (!tk.size) continue;
    let c = clusters.find(x => sim(x.tk, tk) >= 0.4);
    if (!c) { c = { issue: p.reason, tk, post_ids: [] }; clusters.push(c); }
    c.post_ids.push(p.post_id);
  }
  clusters.sort((a, b) => b.post_ids.length - a.post_ids.length);
  return {
    theme: g.theme,
    posts: g.posts,
    top_issues: clusters.slice(0, 5).map(c => ({ issue: c.issue, posts: c.post_ids.length })),
  };
});

if (!summaries.length) throw new Error('All tagged posts were "Not relevant" - no themes to analyse.');
return summaries.map(x => ({ json: x }));

// Count Unique Evidence: count unique posts per theme, track source distribution
const groups = $input.all().map(i => i.json);
const textById = {};
for (const b of $('Clean & Prepare').all()) for (const p of b.json.posts) textById[p.post_id] = p.text;

const norm = (t) => String(t || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const tally = (arr, key) => arr.reduce((m, p) => { m[p[key]] = (m[p[key]] || 0) + 1; return m; }, {});
const DROP = new Set(['Paused', 'Reduced', 'Stopped']);
const isExplicit = (p) => p.explicit === true || String(p.explicit).toLowerCase() === 'true';

const allUnique = new Set();
const themes = groups.map(g => {
  const ids = new Set();
  const quotes = new Set();
  const unique = [];
  for (const p of g.posts) {
    const q = norm(p.quote);
    if (ids.has(p.post_id) || (q.length > 20 && quotes.has(q))) continue; // same post or same quote = one piece of evidence
    ids.add(p.post_id);
    if (q) quotes.add(q);
    unique.push(p);
    allUnique.add(p.post_id);
  }
  // evidence sample for the insight step: stated first, then paused/reduced/stopped first
  const sample = [...unique].sort((a, b) =>
    (isExplicit(b) - isExplicit(a)) || (DROP.has(b.behaviour) - DROP.has(a.behaviour)));
  return {
    theme: g.theme,
    unique_posts: unique.length,
    source_distribution: tally(unique, 'source'),
    behaviour_counts: tally(unique, 'behaviour'),
    explicit_count: unique.filter(isExplicit).length,
    inferred_count: unique.filter(p => !isExplicit(p)).length,
    top_issues: g.top_issues,
    evidence: sample.slice(0, 15).map(p => ({
      post_id: p.post_id, source: p.source, behaviour: p.behaviour, reason: p.reason,
      quote: p.quote, text: String(textById[p.post_id] || '').slice(0, 400),
    })),
  };
}).sort((a, b) => b.unique_posts - a.unique_posts);

// Research questions: how many posts speak to each one + a sample for the AI to summarise
const tags = $('Parse Tags').all().map(i => i.json);
const QUESTIONS = [
  ['Q1', 'Why do people start a SIP, and what do they expect to happen?', 'Q1 Why they started & what they expected'],
  ['Q2', 'What changes in their behaviour in the months after starting?', 'Q2 What changed after starting'],
  ['Q3', 'What leads investors to pause, reduce or stop a SIP?', 'Q3 Why they paused, reduced or stopped'],
  ['Q4', 'What do investors check, and how often, once they have started?', 'Q4 What they check & how often'],
  ['Q5', 'What confuses or worries them inside the app?', 'Q5 What confuses or worries them in the app'],
  ['Q6', 'What do they do outside the app when they feel unsure?', 'Q6 What they do outside the app when unsure'],
  ['Q7', 'What separates investors who continue from those who quietly drop off?', 'Q7 Continue vs drop-off signal'],
  ['Q8', 'How do these patterns differ across user segments (income stability, age, source of money, who influenced them)?', null],
  ['Q9', 'What unmet needs emerge consistently across conversations?', 'Q9 Unmet need'],
];
const segKeys = ['income_stability', 'age', 'source_of_money', 'influenced_by'];
const questions = QUESTIONS.map(([id, question, col]) => {
  const hits = col
    ? tags.filter(t => t[col])
    : tags.filter(t => segKeys.some(k => t.segments && t.segments[k]));
  const sample = [...hits].sort((a, b) => (b.quote_ok - a.quote_ok) || (isExplicit(b) - isExplicit(a))).slice(0, 12)
    .map(t => ({
      post_id: t.post_id, source: t.source, behaviour: t.behaviour,
      answer: col ? t[col] : segKeys.map(k => t.segments[k] ? `${k}: ${t.segments[k]}` : '').filter(Boolean).join('; '),
      quote: t.quote, text: String(textById[t.post_id] || '').slice(0, 300),
    }));
  return { id, question, posts_answering: hits.length, sample };
});

// Segment comparison (Q8): continuing vs dropping off, by each segment value
const segments = segKeys.map(k => {
  const groups = {};
  for (const t of tags) {
    const v = String((t.segments || {})[k] || '').trim().toLowerCase();
    if (!v) continue;
    const g = groups[v] = groups[v] || { value: v, posts: 0, continuing: 0, dropping_off: 0 };
    g.posts++;
    if (t.behaviour === 'Continuing' || t.behaviour === 'Started') g.continuing++;
    if (DROP.has(t.behaviour)) g.dropping_off++;
  }
  return { segment: k, values: Object.values(groups).sort((a, b) => b.posts - a.posts).slice(0, 6) };
});

return [{ json: { themes, questions, segments, total_unique_relevant_posts: allUnique.size, total_tagged_posts: tags.length } }];

// Evidence Validation: verify quotes & sources, check classification, flag inconsistencies
const s = $('Setup & Config Check').first().json;
const cue = $('Count Unique Evidence').first().json;
const tags = $('Parse Tags').all().map(i => i.json);
const tagById = {};
for (const t of tags) tagById[t.post_id] = t;

// source text for every post in this run (cleaned text + original saved text)
const textById = {};
for (const b of $('Clean & Prepare').all()) for (const p of b.json.posts) textById[p.post_id] = p.text;
for (const r of $('Read Saved Data').all()) {
  const j = r.json;
  if (String(j['Run ID']) !== s.run_id) continue;
  const id = String(j['Post ID']);
  textById[id] = (textById[id] || '') + ' ' + String(j['Text'] || '');
}
const norm = (t) => String(t || '').toLowerCase().normalize('NFKC')
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
  .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

const out = $input.first().json;
const raw = String(out.text ?? out.output ?? '');
let parsed;
try {
  const c = raw.replace(/```(?:json)?/gi, '').trim();
  try { parsed = JSON.parse(c); } catch (e) { parsed = JSON.parse((c.match(/\{[\s\S]*\}/) || [''])[0]); }
} catch (e) {
  throw new Error('Generate Insights did not return valid JSON. Output was: ' + raw.slice(0, 300));
}
const themeAnswers = Array.isArray(parsed.themes) ? parsed.themes : [];
const qAnswers = Array.isArray(parsed.research_questions) ? parsed.research_questions : [];
if (!themeAnswers.length) throw new Error('Generate Insights returned no themes.');

const statsByTheme = {};
for (const t of cue.themes) statsByTheme[t.theme] = t;
const qById = {};
for (const q of cue.questions) qById[q.id] = q;

const checks = []; // every quote the AI used, checked against the original post
function checkQuote(itemLabel, ev, expectTheme, allowedIds) {
  const pid = String(ev.post_id || '');
  const quote = String(ev.quote || '');
  const tag = tagById[pid];
  const text = textById[pid];
  const nq = norm(quote);
  const quoteFound = !!(text && nq.length >= 3 && norm(text).includes(nq));
  let result = 'Accepted';
  let why = 'Quote found word-for-word in the post' + (expectTheme ? ' and the post carries this theme' : '');
  if (!tag && !text) { result = 'Rejected'; why = 'Post ID is not in this run - the AI made it up'; }
  else if (allowedIds && !allowedIds.has(pid)) { result = 'Flagged'; why = 'Post was not in the evidence given for this item'; }
  else if (!quoteFound) { result = 'Rejected'; why = 'Quote is not word-for-word in the post (AI paraphrased or invented it)'; }
  else if (expectTheme && !String(tag.theme).split(', ').includes(expectTheme)) { result = 'Flagged'; why = 'Post was labelled with a different theme: ' + tag.theme; }
  checks.push({
    item: itemLabel, post_id: pid, source: tag ? tag.source : '', quote,
    ai_theme: tag ? tag.theme : '', ai_behaviour: tag ? tag.behaviour : '',
    result, why, url: tag ? tag.url : '',
  });
  return result === 'Accepted';
}

const insights = themeAnswers.map((ins, idx) => {
  const theme = String(ins.theme || '').trim();
  const st = statsByTheme[theme];
  const insightId = 'INS-' + String(idx + 1).padStart(2, '0');
  const flags = [];
  if (!st) flags.push('theme not found in labelled data');
  const allowed = st ? new Set(st.evidence.map(e => e.post_id)) : null;
  const evs = Array.isArray(ins.evidence) ? ins.evidence : [];
  let verified = 0;
  const verifiedIds = [];
  for (const ev of evs) {
    if (checkQuote(`${insightId} ${theme}`, ev, theme, allowed)) { verified++; verifiedIds.push(String(ev.post_id)); }
  }
  if (!evs.length) flags.push('no evidence cited');
  if (evs.length && verified < evs.length) flags.push(`${evs.length - verified} of ${evs.length} quotes rejected or flagged`);
  if (st && st.unique_posts < 3) flags.push(`thin evidence: only ${st.unique_posts} unique posts`);
  for (const k of ['severity', 'addressability', 'uncertainty']) {
    const v = Number(ins[k]);
    if (!(v >= 1 && v <= 5)) flags.push(`${k} score missing or out of range`);
  }
  return {
    insight_id: insightId, theme,
    insight: String(ins.insight || ''), what_it_means: String(ins.what_it_means || ''),
    opportunity: String(ins.opportunity || ''),
    severity: ins.severity, severity_reason: String(ins.severity_reason || ''),
    addressability: ins.addressability, addressability_reason: String(ins.addressability_reason || ''),
    uncertainty: ins.uncertainty, uncertainty_note: String(ins.uncertainty_note || ''),
    unique_posts: st ? st.unique_posts : 0,
    source_distribution: st ? st.source_distribution : {},
    behaviour_counts: st ? st.behaviour_counts : {},
    evidence_post_ids: verifiedIds,
    cited_evidence: evs.length, verified_evidence: verified,
    validation_status: verified === 0 ? 'Unverified' : (flags.length ? 'Partially verified' : 'Verified'),
    validation_flags: flags,
  };
});

const questionAnswers = cue.questions.map(q => {
  const a = qAnswers.find(x => String(x.id || '').toUpperCase() === q.id) || {};
  const allowed = new Set(q.sample.map(e => e.post_id));
  const evs = Array.isArray(a.evidence) ? a.evidence : [];
  let verified = 0;
  for (const ev of evs) if (checkQuote(`${q.id} research question`, ev, null, allowed)) verified++;
  return {
    id: q.id, question: q.question, posts_answering: q.posts_answering,
    answer: q.posts_answering ? String(a.answer || 'AI gave no answer') : 'No posts in this run spoke to this question',
    confidence: q.posts_answering ? String(a.confidence || 'Low') : 'None',
    verified_quotes: verified, cited_quotes: evs.length,
    example_quote: (evs.find(ev => checks.some(c => c.post_id === String(ev.post_id) && c.quote === String(ev.quote) && c.result === 'Accepted')) || {}).quote || '',
  };
});

const tagQuotesOk = tags.filter(t => t.quote_ok).length;

return [{
  json: {
    insights,
    question_answers: questionAnswers,
    quote_checks: checks,
    themes: cue.themes,
    segments: cue.segments,
    total_unique_relevant_posts: cue.total_unique_relevant_posts,
    tagging_quote_check: { verbatim: tagQuotesOk, total: tags.length },
    themes_without_insight: cue.themes.filter(t => !insights.some(o => o.theme === t.theme)).map(t => t.theme),
  },
}];

// Compare Opportunities: score using criteria (frequency, severity, evidence, addressability, uncertainty)
const d = $input.first().json;
const clamp = (v) => Math.min(5, Math.max(1, Math.round(Number(v))));
const valid = (v) => Number(v) >= 1 && Number(v) <= 5;
const maxPosts = Math.max(1, ...d.insights.map(i => i.unique_posts || 0));

const opportunities = d.insights.map(i => {
  const sources = Object.keys(i.source_distribution || {}).length;
  const frequency = clamp(Math.ceil(5 * (i.unique_posts || 0) / maxPosts) || 1);
  const evidence = i.verified_evidence === 0
    ? 1
    : clamp((Math.min(i.verified_evidence, 4) / 4) * 3 + (Math.min(sources, 3) / 3) * 2);
  // missing AI scores are treated conservatively
  const severity = valid(i.severity) ? clamp(i.severity) : 1;
  const addressability = valid(i.addressability) ? clamp(i.addressability) : 1;
  const uncertainty = valid(i.uncertainty) ? clamp(i.uncertainty) : 5;
  return {
    insight_id: i.insight_id,
    theme: i.theme,
    opportunity: i.opportunity,
    unique_posts: i.unique_posts,
    sources,
    verified_evidence: i.verified_evidence,
    cited_evidence: i.cited_evidence,
    validation_status: i.validation_status,
    frequency,
    severity,
    evidence_strength: evidence,
    addressability,
    uncertainty,
    // higher uncertainty lowers the score (6 - uncertainty); max total = 25
    total_score: frequency + severity + evidence + addressability + (6 - uncertainty),
    severity_reason: i.severity_reason,
    addressability_reason: i.addressability_reason,
    uncertainty_note: i.uncertainty_note,
  };
});

return [{ json: { ...d, opportunities } }];

// Rank & Prioritize: top opportunities with the reasoning for each rank
const d = $input.first().json;
const ranked = [...d.opportunities].sort((a, b) =>
  (b.total_score - a.total_score) || (b.frequency - a.frequency) || (b.evidence_strength - a.evidence_strength));
const n = ranked.length;

const opportunities = ranked.map((o, idx) => {
  const rank = idx + 1;
  const reasoning = `#${rank} of ${n}, total ${o.total_score}/25. ` +
    `Frequency ${o.frequency}/5 (${o.unique_posts} unique post${o.unique_posts === 1 ? '' : 's'} from ${o.sources} source${o.sources === 1 ? '' : 's'}); ` +
    `severity ${o.severity}/5 (${o.severity_reason}); ` +
    `evidence ${o.evidence_strength}/5 (${o.verified_evidence} of ${o.cited_evidence} quotes verified, ${o.validation_status}); ` +
    `addressability ${o.addressability}/5 (${o.addressability_reason}); ` +
    `uncertainty ${o.uncertainty}/5 (${o.uncertainty_note}).`;
  return { rank, top_pick: rank <= 3, ...o, reasoning };
});

return [{ json: { ...d, opportunities } }];

// Create Final Report: builds the rows for "1 Summary", "3 Opportunities" and "4 AI Evidence Log"
const s = $('Setup & Config Check').first().json;
const d = $input.first().json;
const all = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const fmt = (o) => Object.entries(o || {}).map(([k, v]) => `${k}: ${v}`).join(', ');
const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
const tags = all('Parse Tags').map(i => i.json);

// ---------- volume per source ----------
const SOURCES = s.source_order;
const countBy = (arr, get) => arr.reduce((m, x) => { const k = get(x); m[k] = (m[k] || 0) + 1; return m; }, {});
const collected = countBy(all('Standardize Data'), i => i.json.source);
const newPosts = countBy(all('Remove Duplicates'), i => i.json.source);
const valid = countBy(all('Validate & Enrich').filter(i => i.json['Status'] === 'Valid'), i => i.json['Source']);
const analysed = {};
const cleanStats = (all('Clean & Prepare')[0] || { json: { stats: {} } }).json.stats;
for (const b of all('Clean & Prepare')) for (const p of b.json.posts) analysed[p.source] = (analysed[p.source] || 0) + 1;
const labelled = countBy(tags, t => t.source);
const fetchNodes = {
  'YouTube': ['YouTube Search Videos', 'YouTube Get Comments'], 'YouTube Transcripts': ['YouTube Get Transcripts', 'YouTube Video Details'],
  'Play Store': ['Play Store Reviews'],
  'App Store': ['App Store Reviews'], 'TradingQ&A': ['TradingQnA Search'], 'Google Search': ['Google Search'],
  'Quora': ['Quora Search'], 'Trustpilot': ['Trustpilot Reviews'],
};
const fetchErrors = {};
for (const [src, nodes] of Object.entries(fetchNodes)) {
  // comments turned off, a video with no captions, or a review page past the last one, are normal - not failures
  const n = nodes.reduce((c, name) => c + all(name).filter(i => i.json && i.json.error && !/disabled|404|not found|hasn't returned any results|no transcript|transcript (is )?(not available|disabled)/i.test(JSON.stringify(i.json.error))).length, 0);
  if (n) fetchErrors[src] = n;
}
const sum = (o) => Object.values(o).reduce((a, b) => a + b, 0);

// ---------- 3 Opportunities ----------
const insByTheme = {};
for (const i of d.insights) insByTheme[i.theme] = i;
const opportunity_rows = d.opportunities.map(o => {
  const i = insByTheme[o.theme] || {};
  return {
    'Run ID': s.run_id,
    'Rank': o.rank,
    'Theme': o.theme,
    'Insight': i.insight || '',
    'What It Means': i.what_it_means || '',
    'Opportunity (How might we)': o.opportunity,
    'Unique Posts': o.unique_posts,
    'Sources': fmt(i.source_distribution),
    'Behaviour Split': fmt(i.behaviour_counts),
    'Frequency (1-5)': o.frequency,
    'Severity (1-5)': o.severity,
    'Evidence Strength (1-5)': o.evidence_strength,
    'Addressability (1-5)': o.addressability,
    'Uncertainty (1-5)': o.uncertainty,
    'Total Score (/25)': o.total_score,
    'Why This Rank': o.reasoning,
    'Still Unclear': o.uncertainty_note,
    'Evidence Post IDs': (i.evidence_post_ids || []).join(', '),
    'Validation': i.validation_status + (i.validation_flags && i.validation_flags.length ? ' - ' + i.validation_flags.join('; ') : ''),
  };
});

// ---------- 4 AI Evidence Log ----------
const evidence_rows = [];
const log = (part, item, x = {}) => evidence_rows.push({
  'Run ID': s.run_id, 'Part': part, 'Item': item,
  'Post ID': x.post_id || '', 'Source': x.source || '', 'Text or Quote': x.text || '',
  'AI Theme': x.ai_theme || '', 'AI Behaviour': x.ai_behaviour || '',
  'Your Theme (hand label)': '', 'Your Behaviour (hand label)': '', 'Agree? (Yes/No)': '',
  'Check Result': x.result || '', 'Why': x.why || '', 'Link': x.url || '',
});

// Part A - sources and volume analysed
SOURCES.forEach(src => log('A. Sources & volume', src, {
  source: src,
  result: `collected ${collected[src] || 0} -> new ${newPosts[src] || 0} -> valid ${valid[src] || 0} -> analysed ${analysed[src] || 0} -> labelled ${labelled[src] || 0}`,
  why: fetchErrors[src] ? `${plural(fetchErrors[src], 'request')} failed` : 'OK',
}));
log('A. Sources & volume', 'Total', {
  result: `collected ${sum(collected)} -> new ${sum(newPosts)} -> valid ${sum(valid)} -> SIP-related ${cleanStats.relevant_found || 0} -> analysed ${cleanStats.analysed || 0} (target ${s.target_relevant_posts}) -> labelled ${tags.length}`,
  why: `Lookback ${s.lookback_days} days (since ${s.after_date}). Removed: ${cleanStats.invalid || 0} invalid, ${cleanStats.too_short_after_cleaning || 0} too short, ${cleanStats.not_sip_related || 0} not about SIPs.`,
});

// spoken (video transcripts) vs written posts
const trVideos = all('Pick Transcript Videos').filter(i => i.json && i.json.video_id).length;
const trWithText = all('YouTube Get Transcripts').filter(i => i.json && !i.json.error && Array.isArray(i.json.transcript) && i.json.transcript.length).length;
const trWindows = all('Standardize Data').filter(i => i.json.source_type === 'transcript');
const trSponsored = trWindows.filter(i => /^\[possible sponsored/i.test(String(i.json.title || ''))).length;
const spoken = analysed['YouTube Transcripts'] || 0;
const written = (cleanStats.analysed || 0) - spoken;
log('A. Sources & volume', 'Spoken vs written', {
  result: `spoken ${spoken} + written ${written} = ${cleanStats.analysed || 0} analysed`,
  why: `${trWithText} of ${trVideos} videos had captions; ${trWindows.length} windows of ~${s.transcript_window_seconds}s cut around SIP/${s.app_name} mentions; ${trSponsored} of them from videos that look sponsored or carry referral links. All clips and their labels are in 6 Voice Data.`,
});

// Part B - golden set: posts to label by hand, picked across sources and behaviours
const hash = (t) => { let h = 7; for (const c of String(t)) h = (h * 31 + c.charCodeAt(0)) | 0; return h; };
const pool = {};
for (const t of tags) (pool[t.source] = pool[t.source] || []).push(t);
for (const list of Object.values(pool)) {
  list.sort((a, b) => hash(a.post_id) - hash(b.post_id));
  // spread behaviours: interleave by behaviour inside each source
  const byB = {};
  for (const t of list) (byB[t.behaviour] = byB[t.behaviour] || []).push(t);
  const mixed = [];
  const qs = Object.values(byB);
  while (qs.some(q => q.length)) for (const q of qs) if (q.length) mixed.push(q.shift());
  list.splice(0, list.length, ...mixed);
}
const golden = [];
const queues = Object.values(pool);
while (golden.length < s.golden_set_size && queues.some(q => q.length)) {
  for (const q of queues) if (q.length && golden.length < s.golden_set_size) golden.push(q.shift());
}
golden.forEach((t, i) => log('B. Golden set (label by hand)', `G${String(i + 1).padStart(2, '0')}`, {
  post_id: t.post_id, source: t.source, text: String(t.text).slice(0, 600),
  ai_theme: t.theme, ai_behaviour: t.behaviour, url: t.url,
  result: 'Waiting for your label', why: 'Fill Your Theme + Your Behaviour, then Agree? = Yes if both match the AI',
}));

// Part C - automatic quality checks: where AI output was accepted, rejected or corrected
for (const c of d.quote_checks) {
  log('C. Quality checks', 'Insight quote check - ' + c.item, {
    post_id: c.post_id, source: c.source, text: c.quote, ai_theme: c.ai_theme, ai_behaviour: c.ai_behaviour,
    result: c.result, why: c.why, url: c.url,
  });
}
for (const t of tags.filter(t => !t.quote_ok)) {
  log('C. Quality checks', 'Label quote check', {
    post_id: t.post_id, source: t.source, text: t.quote || '(no quote given)', ai_theme: t.theme, ai_behaviour: t.behaviour,
    result: 'Rejected', why: 'Evidence quote is not word-for-word in the post, so it is marked "Quote Verified = No" in ' + (t.source_type === 'transcript' ? '6 Voice Data' : '2 Feedback Analysis'), url: t.url,
  });
}
for (const t of tags.filter(t => t.off_list_themes)) {
  log('C. Quality checks', 'Theme outside the allowed list', {
    post_id: t.post_id, source: t.source, text: t.off_list_themes, ai_theme: t.theme, ai_behaviour: t.behaviour,
    result: 'Corrected', why: `AI used "${t.off_list_themes}", which is not in theme_list; it was dropped and the post kept: ${t.theme}`, url: t.url,
  });
}
for (const p of ((tags[0] || {}).tagging_problems || [])) {
  log('C. Quality checks', `Labelling batch ${p.batch}`, {
    result: p.dropped ? 'Rejected' : 'Corrected',
    why: p.why + (p.dropped ? ` (${plural(p.dropped, 'post')} not labelled)` : (p.count ? ` (${p.count} ignored)` : '')),
  });
}
for (const i of d.insights.filter(i => i.validation_flags.length)) {
  log('C. Quality checks', `Insight check - ${i.insight_id} ${i.theme}`, {
    result: i.validation_status === 'Unverified' ? 'Rejected' : 'Flagged', why: i.validation_flags.join('; '),
  });
}
const tq = d.tagging_quote_check;
log('C. Quality checks', 'Label quotes word-for-word (all posts)', {
  result: `${tq.verbatim} of ${tq.total} (${tq.total ? Math.round(100 * tq.verbatim / tq.total) : 0}%)`,
  why: 'Share of AI evidence quotes found exactly in the original post',
});

// ---------- 1 Summary ----------
const summary_rows = [];
const add = (section, item, detail) => summary_rows.push({ 'Run ID': s.run_id, 'Section': section, 'Item': item, 'Detail': String(detail) });

add('Run', 'Research goal', s.research_goal);
add('Run', 'Data analysed', `${cleanStats.analysed || 0} SIP-related posts (target ${s.target_relevant_posts}) from ${Object.keys(analysed).length} sources, out of ${sum(collected)} collected. Lookback ${s.lookback_days} days.`);
add('Run', 'Posts per source (analysed)', SOURCES.map(src => `${src}: ${analysed[src] || 0}`).join(' | '));
add('Run', 'Spoken vs written (analysed)', `${spoken} video clips (tab 6 Voice Data), ${written} written posts (tabs 2 and 5)`);

for (const q of d.question_answers) {
  add('Research questions', `${q.id} ${q.question}`,
    `${q.answer} [${plural(q.posts_answering, 'post')}; confidence ${q.confidence}]` + (q.example_quote ? ` e.g. "${q.example_quote}"` : ''));
}

d.opportunities.filter(o => o.top_pick).forEach(o =>
  add('Top opportunities', `#${o.rank} ${o.theme} (${o.total_score}/25)`, o.opportunity));

const segName = { income_stability: 'Income stability', age: 'Age', source_of_money: 'Source of money', influenced_by: 'Influenced by' };
for (const seg of d.segments) {
  const detail = seg.values.length
    ? seg.values.map(v => `${v.value}: ${plural(v.posts, 'post')} (${v.continuing} continuing, ${v.dropping_off} paused/reduced/stopped)`).join(' | ')
    : 'Not enough posts state this';
  add('Segment comparison', segName[seg.segment] || seg.segment, detail);
}

const ev = d.quote_checks;
const cnt = (r) => ev.filter(c => c.result === r).length;
add('AI quality', 'Insight quotes', `${cnt('Accepted')} accepted, ${cnt('Flagged')} flagged, ${cnt('Rejected')} rejected of ${ev.length} (details in 4 AI Evidence Log, part C)`);
add('AI quality', 'Label quotes word-for-word', `${tq.verbatim} of ${tq.total}`);
add('AI quality', 'Golden set', `${golden.length} posts ready to label by hand in 4 AI Evidence Log, part B`);

d.opportunities.filter(o => o.top_pick && o.uncertainty_note).forEach(o =>
  add('Next steps', `Check for #${o.rank} ${o.theme}`, o.uncertainty_note));
add('Next steps', 'Label the golden set', 'Fill the hand-label columns in 4 AI Evidence Log part B and count Agree? = Yes to get the agreement rate.');
if (Object.keys(fetchErrors).length) add('Next steps', 'Fix sources', `Requests failed for: ${Object.keys(fetchErrors).join(', ')}. Check keys/quota and re-run.`);

return [{ json: { opportunity_rows, evidence_rows, summary_rows } }];

// Pick Transcript Videos: the first <youtube_transcript_videos> videos from the YouTube search (Settings; 0 = off)
const s = $('Setup & Config Check').first().json;
const seen = new Set();
const out = [];
for (const v of $input.all()) {
  if (out.length >= s.youtube_transcript_videos) break;
  const id = v.json.id && v.json.id.videoId;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { video_id: id } });
}
return out;

// Build Voice Rows: every video clip from this run with its AI labels, one row each, for the "6 Voice Data" tab
const s = $('Setup & Config Check').first().json;
const all = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const tagById = {};
for (const t of all('Parse Tags')) tagById[t.json.post_id] = t.json;
const sentToAI = new Set();
for (const b of all('Clean & Prepare')) for (const p of b.json.posts) sentToAI.add(p.post_id);
const SPONSORED = /^\[possible sponsored\/referral\]\s*/i;
const TAG_COLS = ['Theme(s)', 'Behaviour',
  'Q1 Why they started & what they expected', 'Q2 What changed after starting', 'Q3 Why they paused, reduced or stopped',
  'Q4 What they check & how often', 'Q5 What confuses or worries them in the app', 'Q6 What they do outside the app when unsure',
  'Q7 Continue vs drop-off signal', 'Q8 Income stability', 'Q8 Age', 'Q8 Source of money', 'Q8 Influenced by', 'Q9 Unmet need',
  'Evidence Quote', 'Stated or Inferred', 'Quote Verified'];

return all('Validate & Enrich')
  .map(i => i.json)
  .filter(r => r['Type'] === 'transcript' && String(r['Run ID']) === s.run_id)
  .map(r => {
    const sec = Number((String(r['Link'] || '').match(/[?&]t=(\d+)s/) || [])[1] || 0);
    const title = String(r['Title / Context'] || '');
    const tag = tagById[r['Post ID']];
    let aiStatus = 'Labelled';
    if (!tag) {
      if (r['Status'] !== 'Valid') aiStatus = 'Not labelled (' + r['Status'] + ')';
      else if (sentToAI.has(r['Post ID'])) aiStatus = 'Not labelled (AI gave no label)';
      else aiStatus = 'Not labelled (not SIP-related, too short or over the target)';
    }
    const row = {
      'Run ID': r['Run ID'],
      'Post ID': r['Post ID'],
      'Collected At': r['Collected At'],
      'Video Title': title.replace(SPONSORED, ''),
      'Channel': r['Author'],
      'Video Date': r['Post Date'],
      'Clip Start': `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`,
      'Clip Link': r['Link'],
      'Transcript Clip': r['Text'],
      'Possibly Sponsored': SPONSORED.test(title) ? 'Yes' : 'No',
      'Status': r['Status'],
      'AI Status': aiStatus,
    };
    for (const c of TAG_COLS) row[c] = tag ? (tag[c] ?? '') : '';
    return { json: row };
  });
